<script>const type=document.querySelector('[data-opportunity]'),panels=document.querySelector('[data-panel-fields]'),service=document.querySelector('[data-service-fields]');function toggleFields(){const v=type.value;panels.hidden=!['used_panels','repowering','equipment_replacement'].includes(v);service.hidden=v!=='solar_service'}type.addEventListener('change',toggleFields);toggleFields();(()=>{const q=document.querySelector('[name="panel_quantity"]'),u=document.querySelector('[name="asking_price"]'),t=document.querySelector('[name="asking_total_price"]');if(!q||!u||!t)return;let source=u;const calculate=()=>{const qty=parseFloat(q.value);if(!(qty>0))return;if(source===t&&parseFloat(t.value)>=0)u.value=(parseFloat(t.value)/qty).toFixed(2);else if(parseFloat(u.value)>=0)t.value=(parseFloat(u.value)*qty).toFixed(2)};u.addEventListener('input',()=>{source=u;calculate()});t.addEventListener('input',()=>{source=t;calculate()});q.addEventListener('input',calculate)})();</script>
